import traceback

def ratio(a, b):
    return a / b

def run():
    return ratio(1, 0)

try:
    run()
except Exception as e:
    frames = traceback.extract_tb(e.__traceback__)
    print(type(e).__name__)
    print(" <- ".join(f.name for f in reversed(frames)))
    print(traceback.format_exception_only(type(e), e)[0].strip())

